#pragma once
#include "PluginProcessor.h"
class ModSlider:public juce::Slider,public juce::DragAndDropTarget {
    struct Assignment {juce::String title,depth;int source,slot;bool legacy;
        juce::String description()const{return legacy?(source==7?juce::String("INFINITY:ENV:0"):source<4?"INFINITY:PERFORMANCE:"+juce::String(source):"INFINITY:LFO:"+juce::String(source-4)):(source==9?juce::String("INFINITY:ENV:0"):source<3?"INFINITY:MACRO:"+juce::String(source):source<6?"INFINITY:LFO:"+juce::String(source-3):"INFINITY:PERFORMANCE:"+juce::String(source-6));}
    };
    struct Amount:public juce::Component {
        juce::Label title;juce::Slider slider;juce::TextButton zero{"ZERO"},remove{"REMOVE"};
        std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> binding;
        Amount(SpaceInfinityProcessor& p,const juce::String& id,const juce::String& caption,std::function<void()> erase){setSize(310,130);title.setText(caption,juce::dontSendNotification);title.setBounds(10,5,290,28);slider.setBounds(10,38,290,38);slider.setTextBoxStyle(juce::Slider::TextBoxRight,false,76,25);slider.setSliderStyle(juce::Slider::LinearHorizontal);binding=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,id,slider);slider.setName("Modulation amount");slider.setMouseDragSensitivity(350);slider.textFromValueFunction=[](double v){return (v>0?"+":"")+juce::String(v*100,1)+" %";};slider.valueFromTextFunction=[](const juce::String& s){return s.getDoubleValue()/100;};slider.updateText();zero.setBounds(10,89,90,27);remove.setBounds(190,89,110,27);zero.onClick=[this]{slider.setValue(0,juce::sendNotificationSync);};remove.onClick=std::move(erase);addAndMakeVisible(title);addAndMakeVisible(slider);addAndMakeVisible(zero);addAndMakeVisible(remove);}
    };
    SpaceInfinityProcessor* processor=nullptr;juce::String id;int target=-1;bool hovering=false;juce::RangedAudioParameter* draggedAmount=nullptr;float amountStart=0;bool polarityClick=false;
    std::unique_ptr<Amount> amount;std::unique_ptr<juce::CallOutBox> popup;
    std::vector<Assignment> assignments()const{
        std::vector<Assignment> result;if(!processor||target<0)return result;
        for(int s=0;s<10;++s)for(int slot=0;slot<16;++slot)if(processor->flexibleSourceTarget(s,slot)==target)result.push_back({s==9?juce::String("Amp envelope"):s>=6?processor->macroNames()[s-6]:s<3?processor->state.state.getProperty("macroLabel"+juce::String(s),"Macro "+juce::String(s+4)).toString():"LFO "+juce::String(s-2),processor->flexibleDepthId(s,slot),s,slot,false});
        const int legacy=processor->legacyTargetIndex(id);if(legacy>0)for(int s=0;s<8;++s)for(int slot=0;slot<3;++slot)if(int(processor->state.getRawParameterValue(processor->modulationRouteId(s,slot,false))->load())==legacy){const auto name=s<4?processor->macroNames()[s]:s==7?juce::String("Amp envelope"):"LFO "+juce::String(s-3);result.push_back({name,processor->modulationRouteId(s,slot,true),s,slot,true});}return result;
    }
    Assignment active(const std::vector<Assignment>& routes)const{const auto selected=getTopLevelComponent()->getProperties()["selectedModSource"].toString();for(const auto& a:routes)if(a.description()==selected)return a;const auto depth=getProperties()["selectedModDepth"].toString();for(const auto& a:routes)if(a.depth==depth)return a;return routes.front();}
    bool bipolar(const Assignment& a)const{const auto key=SpaceInfinityProcessor::modulationPolarityId(a.source,a.slot,a.legacy);if(key.isEmpty())return false;const int mode=int(processor->state.getRawParameterValue(key)->load());return a.legacy?(mode==2||(mode==0&&a.source<7&&processor->legacyTargetIndex(id)==25)):mode!=0;}
    void togglePolarity(const Assignment& a){const auto key=SpaceInfinityProcessor::modulationPolarityId(a.source,a.slot,a.legacy);if(key.isEmpty())return;auto* p=processor->state.getParameter(key);const float next=bipolar(a)?(a.legacy?1.0f:0.0f):(a.legacy?2.0f:1.0f);p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(next));p->endChangeGesture();repaint();}
    double rangePosition(const Assignment& a,float sourceValue=1){auto* parameter=processor->state.getParameter(id);const float depth=processor->state.getRawParameterValue(a.depth)->load()*sourceValue;const float base=float(getValue());float value=base;
        if(!a.legacy)value=parameter->convertFrom0to1(juce::jlimit(0.0f,1.0f,parameter->convertTo0to1(base)+depth));
        else {const int t=processor->legacyTargetIndex(id);if(t==1||t==9||t==15||t==18||t==21||t==22)value=base*std::exp2(depth*2);else if(t==4)value=base*std::exp2(depth*3);else value=base+depth*(t==2?.02f:t==3||t==6||t==7||t==8||t==10?.4f:t==5?.45f:t==23||t==24?1:t==25?4:.5f);}
        return valueToProportionOfLength(juce::jlimit(float(getMinimum()),float(getMaximum()),value));}
    void select(const Assignment& a){getProperties().set("selectedModDepth",a.depth);getTopLevelComponent()->getProperties().set("selectedModSource",a.description());getTopLevelComponent()->repaint();}
    juce::String amountText(const Assignment& a)const{const float value=processor->state.getRawParameterValue(a.depth)->load();return (value>0?"+":"")+juce::String(value*100,1)+"%";}
    void erase(const Assignment& a){if(a.legacy){auto* parameter=processor->state.getParameter(processor->modulationRouteId(a.source,a.slot,false));parameter->beginChangeGesture();parameter->setValueNotifyingHost(parameter->convertTo0to1(0));parameter->endChangeGesture();}else processor->assignFlexibleSource(a.source,a.slot,-1);if(popup)popup->dismiss();repaint();}
public:
    void initialiseModulation(SpaceInfinityProcessor& p,const juce::String& parameter){processor=&p;id=parameter;target=p.flexibleTargetIndex(id);if(getName().isEmpty())if(auto* a=p.state.getParameter(id))setName(a->getName(80));getProperties().set("modParam",id);}
    bool isInterestedInDragSource(const SourceDetails& s)override{const auto d=s.description.toString();return processor&&target>=0&&(d.startsWith("INFINITY:LFO:")||d.startsWith("INFINITY:MACRO:")||d.startsWith("INFINITY:PERFORMANCE:")||d=="INFINITY:ENV:0");}
    void itemDragEnter(const SourceDetails&)override{hovering=true;repaint();}
    void itemDragExit(const SourceDetails&)override{hovering=false;repaint();}
    void itemDropped(const SourceDetails& s)override{hovering=false;if(processor&&processor->dropModulation(s.description.toString(),id)){const auto depth=processor->modulationDepthFor(s.description.toString(),id);for(const auto& a:assignments())if(a.depth==depth){select(a);break;}}repaint();}
    juce::String getTooltip()override{const auto routes=assignments();if(routes.empty())return juce::Slider::getTooltip();const auto a=active(routes);return juce::Slider::getTooltip()+"\n"+a.title+": "+amountText(a)+". Drag the small halo, outer ring or Alt-drag the knob; Shift = fine; Shift+Alt-click = direction; right-click = type / invert / remove.";}
    void showAmount(const juce::String& depth,const juce::String& caption){if(!processor||depth.isEmpty())return;for(const auto& a:assignments())if(a.depth==depth){select(a);break;}popup.reset();amount.reset();juce::Component::SafePointer<ModSlider> safe(this);amount=std::make_unique<Amount>(*processor,depth,caption,[safe,depth]{if(safe)for(const auto& a:safe->assignments())if(a.depth==depth){safe->erase(a);break;}});auto* parent=getParentComponent()?getTopLevelComponent():nullptr;const auto anchor=parent?parent->getLocalArea(this,getLocalBounds()):getScreenBounds();popup=std::make_unique<juce::CallOutBox>(*amount,anchor,parent);popup->setLookAndFeel(&getLookAndFeel());popup->enterModalState(true,nullptr,false);}
    void mouseDown(const juce::MouseEvent& e)override{if(processor&&isRotary()&&!e.mods.isPopupMenu()){const auto routes=assignments();auto bounds=getLocalBounds().toFloat();if(getTextBoxPosition()==juce::Slider::TextBoxBelow)bounds.removeFromBottom(float(getTextBoxHeight()));const float radius=juce::jmin(43.0f,juce::jmin(bounds.getWidth(),bounds.getHeight())*.44f)*1.13f;if(!routes.empty()&&(e.mods.isAltDown()||std::abs(e.position.getDistanceFrom(bounds.getCentre())-radius)<4||e.position.getDistanceFrom(bounds.getCentre().getPointOnCircumference(radius,-juce::MathConstants<float>::pi*.25f))<6)){const auto a=active(routes);select(a);draggedAmount=processor->state.getParameter(a.depth);amountStart=draggedAmount->convertFrom0to1(draggedAmount->getValue());polarityClick=e.mods.isAltDown()&&e.mods.isShiftDown();draggedAmount->beginChangeGesture();return;}}
        if(!processor||!e.mods.isPopupMenu()){juce::Slider::mouseDown(e);return;}const auto routes=assignments();juce::PopupMenu menu;for(size_t i=0;i<routes.size();++i){menu.addItem(100+int(i),routes[i].title+" amount...");menu.addItem(2000+int(i),"Invert "+routes[i].title+" amount");menu.addItem(1000+int(i),"Remove "+routes[i].title);if(SpaceInfinityProcessor::modulationPolarityId(routes[i].source,routes[i].slot,routes[i].legacy).isNotEmpty())menu.addItem(3000+int(i),bipolar(routes[i])?"Use unidirectional "+routes[i].title:"Use bidirectional "+routes[i].title);}if(routes.empty())menu.addItem(1,"Drag an LFO, AMP ENV or macro here",false);juce::Component::SafePointer<ModSlider> safe(this);menu.showMenuAsync(juce::PopupMenu::Options{}.withTargetComponent(this),[safe,routes](int action){if(!safe||action<100)return;const bool polarity=action>=3000,invert=!polarity&&action>=2000,remove=!polarity&&!invert&&action>=1000;const int i=action-(polarity?3000:invert?2000:remove?1000:100);if(i<0||i>=int(routes.size()))return;const auto a=routes[size_t(i)];safe->select(a);if(polarity)safe->togglePolarity(a);else if(invert){auto* p=safe->processor->state.getParameter(a.depth);p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(-p->convertFrom0to1(p->getValue())));p->endChangeGesture();safe->repaint();}else if(remove)safe->erase(a);else safe->showAmount(a.depth,a.title+" -> "+safe->getName());});}
    void mouseDrag(const juce::MouseEvent& e)override{if(draggedAmount){if(e.getDistanceFromDragStart()>3)polarityClick=false;const float value=juce::jlimit(-1.0f,1.0f,amountStart-float(e.getDistanceFromDragStartY())/(e.mods.isShiftDown()?1600:160));draggedAmount->setValueNotifyingHost(draggedAmount->convertTo0to1(value));repaint();}else juce::Slider::mouseDrag(e);}
    void mouseUp(const juce::MouseEvent& e)override{if(draggedAmount){draggedAmount->endChangeGesture();draggedAmount=nullptr;if(polarityClick){const auto routes=assignments();if(!routes.empty())togglePolarity(active(routes));}polarityClick=false;repaint();}else juce::Slider::mouseUp(e);}
    void mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& wheel)override{const auto routes=assignments();if(processor&&e.mods.isAltDown()&&!routes.empty()){auto* a=processor->state.getParameter(active(routes).depth);a->beginChangeGesture();a->setValueNotifyingHost(a->convertTo0to1(juce::jlimit(-1.0f,1.0f,a->convertFrom0to1(a->getValue())+wheel.deltaY*(e.mods.isShiftDown()?.02f:.2f))));a->endChangeGesture();repaint();}else juce::Slider::mouseWheelMove(e,wheel);}
    void paint(juce::Graphics& g)override{const auto routes=assignments();if(!routes.empty()){const auto a=active(routes);getProperties().set("modDepth",double(processor->state.getRawParameterValue(a.depth)->load()));getProperties().set("modStart",rangePosition(a,bipolar(a)?-1:0));getProperties().set("modEnd",rangePosition(a));const auto description=a.description();auto colour=juce::Colour(description.startsWith("INFINITY:ENV:")?0xffff72bb:description.startsWith("INFINITY:LFO:")?0xff5cebd5:0xffbd95ff);if(processor->state.getRawParameterValue(a.depth)->load()<0)colour=colour.brighter(.25f);getProperties().set("modColour",juce::int64(colour.getARGB()));}else {getProperties().remove("modDepth");getProperties().remove("modEnd");getProperties().remove("modStart");}juce::Slider::paint(g);if(!routes.empty()&&!isRotary()){g.setColour(juce::Colour(0xffbd95ff));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(1),3,.8f);}if(hovering){g.setColour(juce::Colour(0xffd7acff));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(1),4,2);}if(draggedAmount){const float v=draggedAmount->convertFrom0to1(draggedAmount->getValue());const auto label=juce::Rectangle<float>(0,0,float(getWidth()),14);g.setColour(juce::Colour(0xf5100b19));g.fillRoundedRectangle(label,2);g.setColour(juce::Colour(0xffb7ffee));g.setFont(juce::Font(juce::FontOptions(10)));g.drawText((v>0?"+":"")+juce::String(v*100,1)+"%",label,juce::Justification::centred);}}
    ~ModSlider()override{if(draggedAmount)draggedAmount->endChangeGesture();popup.reset();amount.reset();}
};
class SpringPitchWheel final:public ModSlider {
    double previousDown=-1,previousUp=-1;
public:
    void setTravel(double down,double up){if(down==previousDown&&up==previousUp)return;previousDown=down;previousUp=up;
        if(down==0&&up==0){setEnabled(false);setValue(0,juce::dontSendNotification);return;}setEnabled(true);
        juce::NormalisableRange<double> range(-down,up,
            [down,up](double,double,double t){return t<.5?(t-.5)*2*down:(t-.5)*2*up;},
            [down,up](double,double,double value){return value<0?(down>0?.5+.5*value/down:.5):(up>0?.5+.5*value/up:.5);},
            [down,up](double,double,double value){return juce::jlimit(-down,up,value);});setNormalisableRange(range);
    }

    void mouseUp(const juce::MouseEvent& e)override{if(!e.mods.isPopupMenu())setValue(0,juce::sendNotificationSync);ModSlider::mouseUp(e);}
};
class ModSourceButton:public juce::TextButton {
public:
    juce::String description;
    void mouseDown(const juce::MouseEvent& e)override{getTopLevelComponent()->getProperties().set("selectedModSource",description);getTopLevelComponent()->repaint();juce::TextButton::mouseDown(e);}
    void mouseDrag(const juce::MouseEvent& e)override{if(e.getDistanceFromDragStart()>5)if(auto* c=juce::DragAndDropContainer::findParentDragContainerFor(this))if(!c->isDragAndDropActive())c->startDragging(description,this);}
};
inline void configureTimeKnob(juce::Slider& slider){auto range=juce::NormalisableRange<double>(slider.getMinimum(),slider.getMaximum(),.00001);range.setSkewForCentre(juce::jlimit(range.start+.00001,range.end-.00001,.025));slider.setNormalisableRange(range);slider.setMouseDragSensitivity(350);slider.textFromValueFunction=[](double v){return v<.1?juce::String(v*1000,2)+" ms":juce::String(v,3)+" s";};slider.valueFromTextFunction=[](const juce::String& s){return s.getDoubleValue()/(s.containsIgnoreCase("ms")?1000:1);};slider.setTooltip("Fine timing near zero. Shift-drag for precision; type ms or seconds; double-click resets.");slider.updateText();}
